2: #import <UIKit/UIKit.h>
3: #import <Preferences/PSListController.h>
4: #import <Preferences/PSSpecifier.h>
5: #import <CoreFoundation/CoreFoundation.h>
6: #import <UniformTypeIdentifiers/UniformTypeIdentifiers.h>
7: #import <notify.h>
8: #import <objc/runtime.h>
9: 
10: @interface RSRootListController : PSListController <UIImagePickerControllerDelegate, UINavigationControllerDelegate, UIDocumentPickerDelegate>
11: @end
12: 
13: @implementation RSRootListController
14: - (NSArray *)specifiers {
15:     // Avoid directly referencing PSListController's private _specifiers ivar:
16:     // it is not exported by the SDK-independent Preferences link stub.
17:     static char kRSSpecifiersKey;
18:     NSArray *cached = objc_getAssociatedObject(self, &kRSSpecifiersKey);
19:     if (!cached) {
20:         cached = [self loadSpecifiersFromPlistName:@"Root" target:self];
21:         if (cached) objc_setAssociatedObject(self, &kRSSpecifiersKey, cached, OBJC_ASSOCIATION_RETAIN_NONATOMIC);
22:     }
23:     return cached;
24: }
25: - (void)rsAlert:(NSString *)title message:(NSString *)message {
26:     UIAlertController *a = [UIAlertController alertControllerWithTitle:title message:message preferredStyle:UIAlertControllerStyleAlert];
27:     [a addAction:[UIAlertAction actionWithTitle:@"确定" style:UIAlertActionStyleDefault handler:nil]];
28:     [self presentViewController:a animated:YES completion:nil];
29: }
30: - (void)rsPickPhoto {
31:     if (![UIImagePickerController isSourceTypeAvailable:UIImagePickerControllerSourceTypePhotoLibrary]) {
32:         [self rsAlert:@"无法打开相册" message:@"当前系统不支持相册选择器。"]; return;
33:     }
34:     UIImagePickerController *p = [[UIImagePickerController alloc] init];
35:     p.sourceType = UIImagePickerControllerSourceTypePhotoLibrary;
36:     p.delegate = self;
37:     p.allowsEditing = NO;
38:     [self presentViewController:p animated:YES completion:nil];
39:     [p release];
40: }
41: - (void)rsPickFile {
42:     UIDocumentPickerViewController *p = [[UIDocumentPickerViewController alloc] initForOpeningContentTypes:@[UTTypePNG, UTTypeJPEG, UTTypeImage] asCopy:YES];
43:     p.delegate = self;
44:     [self presentViewController:p animated:YES completion:nil];
45:     [p release];
46: }
47: - (NSString *)rsCustomPath {
48:     return @"/var/mobile/Library/Application Support/RecordingSharingan/eye/custom.png";
49: }
50: - (void)rsNotifyAndSelect:(BOOL)selectCustom {
51:     if (selectCustom) {
52:         CFPreferencesSetAppValue(CFSTR("eyeStyle"), (CFPropertyListRef)[NSNumber numberWithInt:6], CFSTR("com.tu.recordingsharingan.settings"));
53:         CFPreferencesAppSynchronize(CFSTR("com.tu.recordingsharingan.settings"));
54:     }
55:     notify_post("com.tu.recordingsharingan.settings.changed");
56:     [self reloadSpecifiers];
57: }
58: - (void)rsImportImage:(UIImage *)image {
59:     if (!image || image.size.width <= 0 || image.size.height <= 0) {
60:         [self rsAlert:@"导入失败" message:@"无法解码图片，请选择 PNG 或 JPG。"]; return;
61:     }
62:     const CGSize size = CGSizeMake(512,512);
63:     UIGraphicsBeginImageContextWithOptions(size, NO, 1.0);
64:     CGRect rect = CGRectZero;
65:     CGFloat ratio = MIN(size.width/image.size.width, size.height/image.size.height);
66:     rect.size = CGSizeMake(image.size.width*ratio, image.size.height*ratio);
67:     rect.origin = CGPointMake((512-rect.size.width)/2.0, (512-rect.size.height)/2.0);
68:     [image drawInRect:rect];
69:     UIImage *scaled = UIGraphicsGetImageFromCurrentImageContext();
70:     UIGraphicsEndImageContext();
71:     NSData *png = UIImagePNGRepresentation(scaled);
72:     NSString *path = [self rsCustomPath];
73:     NSString *dir = [path stringByDeletingLastPathComponent];
74:     NSError *error = nil;
75:     if (![[NSFileManager defaultManager] createDirectoryAtPath:dir withIntermediateDirectories:YES attributes:nil error:&error] ||
76:         !png || ![png writeToFile:path options:NSDataWritingAtomic error:&error]) {
77:         [self rsAlert:@"保存失败" message:error.localizedDescription ?: @"无法写入素材文件"]; return;
78:     }
79:     [self rsNotifyAndSelect:YES];
80:     [self rsAlert:@"导入成功" message:@"已生成 512×512 透明 PNG 并选择「自定义 PNG」。素材会随插件设置通知刷新。"];
81: }
82: - (void)rsRemoveCustom {
83:     NSError *err = nil;
84:     NSString *path = [self rsCustomPath];
85:     if ([[NSFileManager defaultManager] fileExistsAtPath:path] &&
86:         ![[NSFileManager defaultManager] removeItemAtPath:path error:&err]) {
87:         [self rsAlert:@"删除失败" message:err.localizedDescription]; return;
88:     }
89:     CFPreferencesSetAppValue(CFSTR("eyeStyle"), (CFPropertyListRef)[NSNumber numberWithInt:1], CFSTR("com.tu.recordingsharingan.settings"));
90:     CFPreferencesAppSynchronize(CFSTR("com.tu.recordingsharingan.settings"));
91:     [self rsNotifyAndSelect:NO];
92:     [self rsAlert:@"已恢复" message:@"已删除自定义素材并切回内置款式 1。"];
93: }
94: - (void)imagePickerControllerDidCancel:(UIImagePickerController *)picker {
95:     [picker dismissViewControllerAnimated:YES completion:nil];
96: }
97: - (void)imagePickerController:(UIImagePickerController *)picker didFinishPickingMediaWithInfo:(NSDictionary *)info {
98:     UIImage *image = [info objectForKey:UIImagePickerControllerOriginalImage];
99:     [image retain];
100:     [picker dismissViewControllerAnimated:YES completion:^{ [self rsImportImage:image]; [image release]; }];
101: }
102: - (void)documentPickerWasCancelled:(UIDocumentPickerViewController *)controller {}
103: - (void)documentPicker:(UIDocumentPickerViewController *)controller didPickDocumentsAtURLs:(NSArray<NSURL *> *)urls {
104:     NSURL *url = [urls firstObject];
105:     if (!url) return;
106:     BOOL access = [url startAccessingSecurityScopedResource];
107:     NSData *data = [NSData dataWithContentsOfURL:url];
108:     if (access) [url stopAccessingSecurityScopedResource];
109:     UIImage *image = [UIImage imageWithData:data];
110:     [self rsImportImage:image];
111: }
112: @end
